def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_pressure = 0.0
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if bid > opp_pressure:
                    opp_pressure = bid

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water >= 1:
            return float(min(budget, 45.0))
        return float(min(budget, 18.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 6:
        urgency += 0.3

    if no_water >= 2:
        urgency += 1.0
    elif no_water >= 1:
        urgency += 0.55

    urgency += 0.45 * scarcity

    avg_prev = 0.0
    if prev_bids:
        avg_prev = sum(prev_bids) / float(len(prev_bids))

    affordable_cap = min(budget, DAILY_SALARY * 1.15)

    if urgency >= 1.6:
        bid = max(58.0, min(affordable_cap, opp_pressure + 2.5))
    elif urgency >= 1.0:
        target = max(42.0, avg_prev * 0.55 + 6.0)
        if scarcity > 0.7:
            target += 8.0
        bid = min(affordable_cap, target)
    elif urgency >= 0.5:
        target = 24.0 + 16.0 * scarcity
        if opp_pressure > 120:
            target -= 6.0
        bid = min(budget, max(16.0, target))
    else:
        target = 12.0 + 10.0 * scarcity
        if opp_pressure > 110:
            target = min(target, 14.0)
        bid = min(budget, max(8.0, target))

    if day >= 8:
        bid = min(budget, bid + 6.0)
    if hp <= 2:
        bid = min(budget, max(bid, 63.0))
    if no_water >= 2:
        bid = min(budget, max(bid, 66.0))

    if budget < 25:
        bid = min(budget, max(0.0, budget))

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])

    # If we are about to die, bid enough to avoid losing to a high-demand field.
    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.95)

    # Look only at yesterday's previous_trace for immediate reaction.
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        # No competition: bid conservatively but still secure water.
        return min(my_budget, DAILY_SALARY * 0.45)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate aggressiveness from yesterday.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: with medium scenario supply is between 15 and 25.
    # Higher supply reduces the need to overbid, but yesterday showed strong bidding anyway.
    supply_factor = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)  # 0..1

    # Core strategy:
    # - If yesterday bids were very high, match the field by bidding near the average/high.
    # - Otherwise, bid moderately above a baseline to secure at least one unit of water.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Field is aggressive; bid to avoid being the one who misses water.
        target = avg_prev_bid + 3.0
    else:
        # Less aggressive field; still bid above baseline.
        target = max(DAILY_SALARY * (0.50 + 0.10 * (1.0 - supply_factor)), avg_prev_bid * 0.9)

    # Cap by budget and keep some buffer.
    # If budget is low, bid more to prevent cascading no-water days.
    budget_pressure = 0.0
    if DAILY_SALARY > 0:
        budget_pressure = max(0.0, (DAILY_SALARY * 1.0 - my_budget) / (DAILY_SALARY * 1.0))

    if budget_pressure > 0.3:
        target = target * (1.0 + 0.25 * budget_pressure)

    # Final clamp.
    upper = DAILY_SALARY * 0.95
    bid = min(float(my_budget), float(target), upper)

    # Ensure non-trivial bid.
    min_bid = DAILY_SALARY * 0.35
    if bid < min_bid:
        bid = min(float(my_budget), min_bid)

    return float(bid)
